mapper.select:
SELECT ct.id as id, ct.business_type as businessType, ct.template_name as templateName, ct.title as title, ct.is_default as isDefault, ct.contract_type as contractType, ct.contract_document_type as contractDocumentType, ct.creater as creater, ct.create_time as createTime, ct.enabled_status as enabledStatus, ct.applicable_object_type as applicableObjectType, '适用默认的对象' AS applyCompanyName FROM contract_template ct
IFNULL(ct.is_delete, 0) != 1
and (ct.company_id = #{templateListQryParam.companyId} or ct.company_id is null)
and instr(ct.template_name, #{templateListQryParam.contractTemplateName})
and ct.contract_type = #{templateListQryParam.templateContractType}
and ct.contract_document_type = #{templateListQryParam.templateDocumentType}
and ct.enabled_status = #{templateListQryParam.enabledStatus}
and ct.applicable_object_type = 1 and instr(ctc.company_name,#{templateListQryParam.applicableObjectName})
and ((date_format(ct.create_time,'%Y-%m-%d %H:%i:%S') >= date_format(#{templateListQryParam.createStartTime,jdbcType=VARCHAR},'%Y-%m-%d %H:%i:%S')))
and ((date_format(ct.create_time,'%Y-%m-%d %H:%i:%S') <= date_format(#{templateListQryParam.createEndTime,jdbcType=VARCHAR},'%Y-%m-%d %H:%i:%S')))
and ct.business_type = #{templateListQryParam.businessType}
group by ct.id order by ct.create_time desc

SELECT DISTINCT ct.* from contract_template ct left join contract_template_company ctm on ct.id = ctm.contract_template_id
ifnull(ct.is_delete, 0) != 1 and ct.applicable_object_type = 1 and enabled_status = 1
and ct.contract_document_type = #{documentType}
and ct.business_type = #{contractBusinessType}
and ctm.company_id in
#{ids}
ORDER BY ct.create_time desc
